std::vector<int> data = {1, 5, 2, 8};

// Standard Range iteration (C++11+)
for (int& value : data) {
    value *= 2;
}


std::set<std::string> names = {"Zoe", "Amy", "Carl"};
std::vector<std::string> output;

// Use algorithm std::copy on a range
std::copy(names.begin(), names.end(),
          std::back_inserter(output));


std::vector<int> numbers = {3, 1, 4, 1, 5, 9};

// Algorithm application (Range defined by iterators)
std::sort(numbers.begin(), numbers.end());


std::map<int, std::string> lookup = {{1, "One"}, {2, "Two"}};

// Range-based loop unpacking pair elements (C++17 structured binding)
for (const auto& [key, value] : lookup) {
    std::cout << key << ": " << value;
}


// C++20 Ranges: Filtering and Transforming
std::vector<int> source = {1, 2, 3, 4, 5};

auto evens_squared = source
    | std::views::filter([](int x) { return x % 2 == 0; })
    | std::views::transform([](int x) { return x * x; });

// evens_squared range contains: {4, 16}
std::vector<int> result(evens_squared.begin(), evens_squared.end());
